/**
 * 발송 실패한 알림 가운데 다음 회차에 다시 싣는 것.
 * 여기 든 사유로 실패한 알림은 이벤트를 미발송으로 되돌리고, 소비자도 그 키를 처리한 것으로 치지 않는다.
 * 그 밖의 실패는 회차 리포트의 '실패'로만 남는다.
 */
const RESEND_ON: ReadonlySet<string> = new Set<string>([
  // TODO: 1.9.0부터 비어 있음. 재발송 기능째 걷어낼지, 아직 필요한지 확인 필요
]);

export function shouldResend(reason: string): boolean {
  return RESEND_ON.has(reason);
}
import { DispatchRun } from "../domain/notification";
import { AlertPublisher } from "../messaging/eventPublisher";
import { AlertConsumer } from "../notifier/consumerWorker";
import { CustomerRepository } from "../repository/customerRepository";
import { DeliveryLogRepository } from "../repository/deliveryLogRepository";
import { OrderRepository } from "../repository/orderRepository";
import { planNotifications } from "./notificationPlanner";
import { shouldResend } from "./resendPolicy";

/** 발송 회차: 미발송 이벤트 → 알림 계획 → 발행(1배치) → 소비·문자 발송 → (재발송 대상 되돌림) → 회차 기록 */
export class DispatchService {
  private lastRunId = 0;

  constructor(
    private readonly orders: OrderRepository,
    private readonly customers: CustomerRepository,
    private readonly publisher: AlertPublisher,
    private readonly consumer: AlertConsumer,
    private readonly log: DeliveryLogRepository,
  ) {}

  runOnce(): DispatchRun {
    const runId = ++this.lastRunId;
    const events = this.orders.takePending();
    const plan = planNotifications(events, this.customers);
    const pub = this.publisher.publishRun(plan.notifications);
    const drained = this.consumer.drain(runId);
    for (const f of drained.failed) {
      if (shouldResend(f.reason)) this.orders.requeue(f.orderNo, f.kind);
    }
    const run: DispatchRun = {
      runId,
      planned: plan.notifications,
      skippedOptOut: plan.skippedOptOut,
      published: pub.accepted,
      batch: pub.batch,
      delivered: drained.delivered,
      failed: drained.failed,
    };
    this.log.saveRun(run);
    return run;
  }
}
# 문자 대행사 계약 메모

계약: 문자 발송 대행 기본계약 + 부속서(서비스 수준·응답 코드). 원문은 계약관리 시스템, 이 메모는 개발에 필요한 부분만 옮긴다.
개정 이력: 2024-11 최초 정리 · 2025-08-05 INC-0719 회신 반영(3장).

## 1장 발신 번호·본문
- 발신 번호 1588-0000(사전 등록). 본문 90바이트 이하 단문, 넘으면 장문 과금.

## 2장 처리량
- 계정당 초당 30건. 넘는 요청은 E-THROTTLE로 즉시 돌려준다.

## 3장 실패 응답 처리 (2025-08-05 대행사 회신 반영)
| 코드 | 대행사 처리 | 과금 |
|---|---|---|
| E-THROTTLE | 요청을 받지 않은 것으로 처리(대기열에 넣지 않음). | 없음 |
| E-CARRIER | 대행사 대기열에 남겨 두었다가 통신사 반려가 풀리면 대행사가 같은 메시지를 다시 넣는다(30분 안, 1회). 이 결과는 발송 요청자에게 따로 통보하지 않는다. | 발송 성공 시 1건 |
| E-SPAM | 수신자 단말·통신사 차단. 대행사 처리 없음. | 없음 |

## 4장 정산
- 월 1회 발송 내역(건별)과 청구서 대사. 차이 0.5% 넘으면 재대사 요청.
import { mkdtempSync, rmSync } from "fs";
import { tmpdir } from "os";
import { join } from "path";
import { createApp } from "../src/app";
import { eq, onCleanup, run, test } from "./harness";

interface Report {
  runId: number;
  planned: number;
  delivered: number;
  failed: number;
  lines: { orderNo: string; kind: string; status: string; reason?: string }[];
}

/** 모의 문자 게이트웨이에 번호별 실패 응답을 넣은 앱 하나 */
function world(smsFaults: Record<string, string[]>) {
  const spoolDir = mkdtempSync(join(tmpdir(), "alerts-r-"));
  onCleanup(() => rmSync(spoolDir, { recursive: true, force: true }));
  const app = createApp({ spoolDir, mqpubBin: join(process.cwd(), "vendor", "bin", "mqpub"), smsFaults });
  const call = (method: string, url: string, body?: unknown): unknown => {
    const r = app.handle(method, url, body);
    eq(r.status, 200, `${method} ${url} → ${JSON.stringify(r.body)}`);
    return r.body;
  };
  return {
    customer: (id: string, name: string, phone: string) => call("POST", "/customers", { id, name, phone }),
    order: (customerId: string, placedOn: string) =>
      (call("POST", "/orders", { customerId, placedOn }) as { orderNo: string }).orderNo,
    event: (orderNo: string, kind: string) => call("POST", `/orders/${encodeURIComponent(orderNo)}/events`, { kind }),
    dispatch: () => call("POST", "/dispatch") as Report,
    inbox: (id: string) => (call("GET", `/customers/${id}/alerts`) as { inbox: string[] }).inbox,
  };
}

test("an alert that failed with E-THROTTLE goes out in the next dispatch run", () => {
  const w = world({ "010-5100-0001": ["E-THROTTLE"] });
  w.customer("C5101", "문가온", "010-5100-0001");
  w.customer("C5102", "배하린", "010-5100-0002");
  const a = w.order("C5101", "2026-10-09");
  const b = w.order("C5102", "2026-10-09");
  w.event(a, "SHIPPED");
  w.event(b, "SHIPPED");

  const r1 = w.dispatch();
  eq(r1.lines.find((l) => l.orderNo === a)?.status, "실패", "first run: throttled alert failed");
  eq(r1.lines.find((l) => l.orderNo === b)?.status, "발송", "first run: other alert sent");
  eq(w.inbox("C5101").length, 0, "nothing received yet");

  const r2 = w.dispatch();
  eq(r2.lines.filter((l) => l.orderNo === a).map((l) => l.status), ["발송"], "second run: the failed alert is sent");
  eq(w.inbox("C5101").length, 1, "customer got the shipping text");
  eq(w.inbox("C5101")[0].includes("출발"), true, "shipping wording");
  eq(w.inbox("C5102").length, 1, "other customer is not texted again");

  const r3 = w.dispatch();
  eq(r3.planned, 0, "third run: nothing left to send");
  eq(w.inbox("C5101").length, 1, "still one text");
});

run();

